// WP-4.1 internal: see temporal_pipeline.hpp.
#include "temporal_pipeline.hpp"

#include <fuse/renderer/vk/bindless.hpp>
#include <fuse/renderer/vk/device.hpp>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp41.cmake from shaders/temporal/*: kTm<Kernel><Slang|Glsl>Spv and
// FUSE_TEMPORAL_{SLANG,GLSL} when every kernel of a language exists.
#include "temporal_spv.h"
#endif

namespace fuse::renderer::temporal::detail {

namespace {
constexpr u32 kPushBytes = sizeof(TemporalPush);

#if defined(FUSE_VULKAN_BACKEND)
template <usize N>
KernelCode code(const u32 (&spv)[N], const char* language) {
    return KernelCode{spv, sizeof(spv), language};
}
#endif
} // namespace

KernelCode kernelCode(TemporalKernel kernel, TemporalKernelLanguage language) {
#if defined(FUSE_TEMPORAL_SLANG)
    if (language == TemporalKernelLanguage::Auto || language == TemporalKernelLanguage::Slang) {
        return kernel == TemporalKernel::Motion ? code(kTmMotionSlangSpv, "slang") : code(kTmTaauSlangSpv, "slang");
    }
#endif
#if defined(FUSE_TEMPORAL_GLSL)
    if (language == TemporalKernelLanguage::Auto || language == TemporalKernelLanguage::Glsl) {
        return kernel == TemporalKernel::Motion ? code(kTmMotionGlslSpv, "glsl") : code(kTmTaauGlslSpv, "glsl");
    }
#endif
    (void)kernel;
    (void)language;
    return KernelCode{};
}

bool createComputePipeline(VulkanDevice& device, const BindlessDescriptors& bindless, const KernelCode& code,
                           void*& layoutOut, void*& pipelineOut) {
    layoutOut = nullptr;
    pipelineOut = nullptr;
#if defined(FUSE_VULKAN_BACKEND)
    if (code.words == nullptr) {
        return false;
    }
    const VkDevice vk = static_cast<VkDevice>(device.nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(bindless.layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(vk, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = code.bytes;
    moduleInfo.pCode = code.words;
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(vk, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        vkDestroyPipelineLayout(vk, layout, nullptr);
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.flags = static_cast<VkPipelineCreateFlags>(bindless.pipelineCreateFlags());
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(vk, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(vk, module, nullptr);
    if (result != VK_SUCCESS) {
        vkDestroyPipelineLayout(vk, layout, nullptr);
        return false;
    }
    layoutOut = layout;
    pipelineOut = pipeline;
    return true;
#else
    (void)device;
    (void)bindless;
    (void)code;
    return false;
#endif
}

void destroyComputePipeline(VulkanDevice& device, void*& layout, void*& pipeline) {
#if defined(FUSE_VULKAN_BACKEND)
    const VkDevice vk = static_cast<VkDevice>(device.nativeHandle());
    if (pipeline != nullptr) {
        vkDestroyPipeline(vk, static_cast<VkPipeline>(pipeline), nullptr);
    }
    if (layout != nullptr) {
        vkDestroyPipelineLayout(vk, static_cast<VkPipelineLayout>(layout), nullptr);
    }
#else
    (void)device;
#endif
    pipeline = nullptr;
    layout = nullptr;
}

void dispatch(void* commandBuffer, const BindlessDescriptors& bindless, void* layout, void* pipeline, const void* push,
              u32 groupsX, u32 groupsY) {
#if defined(FUSE_VULKAN_BACKEND)
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(pipeline));
    bindless.bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, layout, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(layout), VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes, push);
    vkCmdDispatch(cmd, groupsX, groupsY, 1u);
#else
    (void)commandBuffer;
    (void)bindless;
    (void)layout;
    (void)pipeline;
    (void)push;
    (void)groupsX;
    (void)groupsY;
#endif
}

} // namespace fuse::renderer::temporal::detail
